USE tickethub_event_db;
SET FOREIGN_KEY_CHECKS = 0;
DELETE FROM show_seats WHERE show_id >= 100;
DELETE FROM shows WHERE show_id >= 100;
DELETE FROM seats WHERE screen_id >= 10;
DELETE FROM screens WHERE screen_id >= 10;
DELETE FROM venues WHERE venue_id >= 10;
DELETE FROM events WHERE event_id >= 10;
SET FOREIGN_KEY_CHECKS = 1;

