-- 4. 27 Top Sci-Fi & Drama Movies with Verified TMDB Posters
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (10, 'Inception', 'Dom Cobb is a skilled thief, the absolute best in the dangerous art of extraction, stealing valuable secrets from deep within the subconscious during the dream state.', 'MOVIE', 'English', 148, 'UA', 'Sci-Fi', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/9gk7adHYeDvHkCSEqAvQNLV5Uge.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (11, 'Interstellar', 'A team of explorers travel through a wormhole in space in an attempt to ensure humanity''s survival as Earth faces catastrophic ecological collapse.', 'MOVIE', 'English', 169, 'UA', 'Sci-Fi', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/gEU2QniE6E77NI6lCU6MxlNBvIx.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (12, 'Dune: Part Two', 'Paul Atreides unites with Chani and the Fremen while seeking revenge against the conspirators who destroyed his family, facing a choice between love and the universe''s fate.', 'MOVIE', 'English', 166, 'UA', 'Sci-Fi', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/1pdfLvkbY9ohJlCjQH2CZjjYVvJ.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (13, 'Blade Runner 2049', 'Thirty years after the events of the first film, a new Blade Runner, LAPD Officer K, unearths a long-buried secret that has the potential to plunge what''s left of society into chaos.', 'MOVIE', 'English', 164, 'A', 'Sci-Fi', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/gajva2L0rPYkEWjzgFlBXCAVBE5.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (14, 'The Matrix', 'When a beautiful stranger leads computer hacker Neo to a forbidding underworld, he discovers the shocking truth--the life he knows is the elaborate deception of an evil cyber-intelligence.', 'MOVIE', 'English', 136, 'A', 'Sci-Fi', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/f89U3ADr1oiB1s9GkdPOEpXUk5H.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (15, 'Avatar: The Way of Water', 'Jake Sully lives with his newfound family on the extrasolar moon Pandora. Once a familiar threat returns, Jake must work with Neytiri to protect their home and their clan.', 'MOVIE', 'English', 192, 'UA', 'Sci-Fi', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/t6HIqrRAclMCA60NsSmeqe9RmNV.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (16, 'Tenet', 'Armed with only one word, Tenet, and fighting for the survival of the entire world, a Protagonist journeys through a twilight world of international espionage on a mission unfolding beyond real time.', 'MOVIE', 'English', 150, 'UA', 'Sci-Fi', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/k68nPLbIST6NP96JmTxmZijEvCA.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (17, 'Oppenheimer', 'The story of American scientist J. Robert Oppenheimer and his role in the development of the atomic bomb during World War II.', 'MOVIE', 'English', 180, 'A', 'Sci-Fi', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/8Gxv8gSFCU0XGDykEGv7zR1n2ua.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (18, 'Arrival', 'A linguist works with the military to communicate with alien lifeforms after twelve mysterious spacecraft appear around the world.', 'MOVIE', 'English', 116, 'UA', 'Sci-Fi', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/x2FJsf1ElAgr63Y3PNPtJrcmpoe.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (19, 'Alien', 'The crew of a commercial spacecraft encounters a deadly lifeform after investigating an unknown transmission on a remote moon.', 'MOVIE', 'English', 117, 'A', 'Sci-Fi', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/vfrQk5IPloGg1v9Rzbh2Eg3VGyM.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (20, 'Avengers: Endgame', 'After the devastating events of Avengers: Infinity War, the universe is in ruins. With the help of remaining allies, the Avengers assemble once more to reverse Thanos'' actions.', 'MOVIE', 'English', 181, 'UA', 'Sci-Fi', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/or06FN3Dka5tukK1e9sl16pB3iy.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (21, 'Star Wars: The Empire Strikes Back', 'After the Rebels are overpowered by the Empire, Luke Skywalker begins Jedi training with Yoda, while his friends are pursued across the galaxy by Darth Vader.', 'MOVIE', 'English', 124, 'U', 'Sci-Fi', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/6FfCtAuVAW8XJjZ7eWeLibRLWTw.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (22, 'Spider-Man: Across the Spider-Verse', 'Miles Morales catapults across the Multiverse, where he encounters a team of Spider-People charged with protecting its very existence.', 'MOVIE', 'English', 140, 'U', 'Sci-Fi', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/8Vt6mWEReuy4Of61Lnj5Xj704m8.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (23, 'The Shawshank Redemption', 'A banker convicted of uxoricide forms a friendship over a quarter of a century with a hardened convict, while maintaining his innocence and trying to remain hopeful through simple compassion.', 'MOVIE', 'English', 142, 'A', 'Drama', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/9cqNxx0GxF0bflZmeSMuL5tnGzr.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (24, 'The Godfather', 'The aging patriarch of an organized crime dynasty transfers control of his clandestine empire to his reluctant youngest son.', 'MOVIE', 'English', 175, 'A', 'Drama', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/3bhkrj58Vtu7enYsRolD1fZdja1.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (25, 'The Dark Knight', 'When the menace known as the Joker wreaks havoc and chaos on the people of Gotham, Batman must accept one of the greatest psychological and physical tests of his ability to fight injustice.', 'MOVIE', 'English', 152, 'UA', 'Drama', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/qJ2tW6WMUDux911r6m7haRef0WH.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (26, '12 Angry Men', 'The jury in a New York City murder trial is frustrated by a single member whose skeptical caution forces them to more carefully consider the evidence before jumping to a hasty verdict.', 'MOVIE', 'English', 96, 'U', 'Drama', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/ow3wq89wM8qd5X7hWKxiRfsFf9C.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (27, 'Schindler''s List', 'In German-occupied Poland during World War II, industrialist Oskar Schindler gradually becomes concerned for his Jewish workforce after witnessing their persecution by the Nazis.', 'MOVIE', 'English', 195, 'A', 'Drama', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/sF1U4EUQS8YHUYjNl3pMGNIQyr0.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (28, 'Pulp Fiction', 'The lives of two mob hitmen, a boxer, a gangster and his wife, and a pair of diner bandits intertwine in four tales of violence and redemption.', 'MOVIE', 'English', 154, 'A', 'Drama', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/d5iIlFn5s0ImszYzBPb8JPIfbXD.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (29, 'Fight Club', 'An insomniac office worker and a devil-may-care soap maker form an underground fight club that evolves into much more.', 'MOVIE', 'English', 139, 'A', 'Drama', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/pB8BM7pdSp6B6Ih7QZ4DrQ3PmJK.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (30, 'Forrest Gump', 'The history of the United States from the 1950s to the ''70s unfolds from the perspective of an Alabama man with an IQ of 75, who yearns to be reunited with his childhood sweetheart.', 'MOVIE', 'English', 142, 'UA', 'Drama', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/arw2vcBveWOVZr6pxd9XTd1TdQa.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (31, 'Whiplash', 'A promising young drummer enrolls at a cut-throat music conservatory where his dreams of greatness are mentored by an instructor who will stop at nothing to realize a student''s potential.', 'MOVIE', 'English', 107, 'A', 'Drama', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/7fn624j5lj3xTme2SgiLCeuedmO.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (32, 'Parasite', 'Greed and class discrimination threaten the newly formed symbiotic relationship between the wealthy Park family and the destitute Kim clan.', 'MOVIE', 'English', 132, 'A', 'Drama', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/7IiTTgloJzvGI1TAYymCfbfl3vT.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (33, 'Gladiator', 'A former Roman General sets out to exact vengeance against the corrupt emperor who murdered his family and sent him into slavery.', 'MOVIE', 'English', 155, 'A', 'Drama', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/ty8TGRuvJLPUmAR1H1nRIsgwvim.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (34, 'Goodfellas', 'The story of Henry Hill and his life in the mafia, covering his relationship with his wife Karen and his mob partners Jimmy Conway and Tommy DeVito.', 'MOVIE', 'English', 145, 'A', 'Drama', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/aKuFiU82s5ISJpGZp7YkIr3kCUd.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (35, 'The Green Mile', 'A tale set on death row in a Southern prison, where gentle giant John Coffey possesses the mysterious power to heal people''s ailments and lives.', 'MOVIE', 'English', 189, 'A', 'Drama', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/o0lO84GI7qrG6XFvtsPOSV7CTNa.jpg');
INSERT INTO events (event_id, title, description, event_type, language, duration, rating, genre, status, poster_url) VALUES (36, 'Se7en', 'Two detectives, a rookie and a veteran, hunt a serial killer who uses the seven deadly sins as his motives.', 'MOVIE', 'English', 127, 'A', 'Drama', 'PUBLISHED', 'https://image.tmdb.org/t/p/w500/6yoghtyTpznpBik8EngEmJskVUO.jpg');

